<script lang="ts">
  import type { TrackedPrediction, Validation } from './types';
  export let metrics: Validation | null;
  export let history: TrackedPrediction[];
  export let loading = false;
  export let onreconcile: () => void;
  const value = (number: number | null | undefined) => number == null ? '—' : number.toFixed(2);
</script>

<main class="validation-page">
  <header><p class="kicker">Model accountability</p><h1>Validation and live results</h1><p>Walk-forward testing measures historical performance. Live tracking records projections before outcomes are known.</p></header>
  {#if metrics}
    <section class="validation-overview"><div><span>Held-out sample</span><strong>{metrics.held_out_rows.toLocaleString()}</strong><small>{metrics.held_out_dates} future dates</small></div><div><span>FIP MAE</span><strong>{metrics.fip_mae.toFixed(3)}</strong><small>Lower is better</small></div><div><span>Runs MAE</span><strong>{metrics.runs_mae.toFixed(3)}</strong><small>{(metrics.calibrated_runs_interval_coverage*100).toFixed(0)}% band coverage</small></div><div><span>Innings MAE</span><strong>{metrics.innings_mae.toFixed(3)}</strong><small>{(metrics.calibrated_innings_interval_coverage*100).toFixed(0)}% band coverage</small></div><div><span>Strikeouts MAE</span><strong>{metrics.strikeouts_mae.toFixed(3)}</strong><small>{(metrics.calibrated_strikeouts_interval_coverage*100).toFixed(0)}% band coverage</small></div></section>
    <section class="confidence-audit" aria-labelledby="confidence-audit-heading"><div class="panel-title"><div><h2 id="confidence-audit-heading">Confidence tier audit</h2><p>Five-start candidate tiers activate only when each has enough later-date starts and realized runs MAE improves by at least {((1-metrics.confidence_calibration.required_mae_ratio)*100).toFixed(0)}% from low → medium → high. Short histories are audited separately.</p></div><span>{metrics.confidence_calibration.tiers_validated ? 'Gate passed' : 'Gate failed · high withheld'}</span></div><div class="validation-overview"><div><span>Confidence tiers</span><strong>{metrics.confidence_calibration.tiers_validated ? 'Validated' : 'Withheld'}</strong><small>{metrics.confidence_audit.rows} later-date starts</small></div><div><span>Candidate high</span><strong>{value(metrics.confidence_audit.high.runs_mae)}</strong><small>Runs MAE · {metrics.confidence_audit.high.rows} starts</small></div><div><span>Candidate medium</span><strong>{value(metrics.confidence_audit.medium.runs_mae)}</strong><small>Runs MAE · {metrics.confidence_audit.medium.rows} starts</small></div><div><span>Candidate low</span><strong>{value(metrics.confidence_audit.low.runs_mae)}</strong><small>Runs MAE · {metrics.confidence_audit.low.rows} starts</small></div><div><span>Short history</span><strong>{value(metrics.confidence_audit.short_history.runs_mae)}</strong><small>Runs MAE · {metrics.confidence_audit.short_history.rows} starts</small></div></div></section>
    <section class="validation-comparison"><div class="panel-title"><div><h2>Model versus simple baselines</h2><p>Each cell is walk-forward mean absolute error</p></div><span>Lower wins</span></div><div class="validation-table"><div><b>Target</b><b>Bayesian</b><b>League</b><b>Pitcher history</b><b>Last five</b></div><div><span>FIP</span><strong>{metrics.fip_mae.toFixed(3)}</strong><span>{metrics.league_fip_mae.toFixed(3)}</span><span>{metrics.pitcher_history_fip_mae.toFixed(3)}</span><span>{metrics.last_five_fip_mae.toFixed(3)}</span></div><div><span>Runs</span><strong>{metrics.runs_mae.toFixed(3)}</strong><span>{metrics.league_runs_mae.toFixed(3)}</span><span>{metrics.pitcher_history_runs_mae.toFixed(3)}</span><span>{metrics.last_five_runs_mae.toFixed(3)}</span></div><div><span>Innings</span><strong>{metrics.innings_mae.toFixed(3)}</strong><span>{metrics.league_innings_mae.toFixed(3)}</span><span>{metrics.pitcher_history_innings_mae.toFixed(3)}</span><span>{metrics.last_five_innings_mae.toFixed(3)}</span></div><div><span>Strikeouts</span><strong>{metrics.strikeouts_mae.toFixed(3)}</strong><span>{metrics.league_strikeouts_mae.toFixed(3)}</span><span>{metrics.pitcher_history_strikeouts_mae.toFixed(3)}</span><span>{metrics.last_five_strikeouts_mae.toFixed(3)}</span></div></div></section>
  {:else}<div class="validation-empty">Run a slate to calculate walk-forward metrics for this session.</div>{/if}

  <section class="live-results"><div class="panel-title"><div><h2>Recorded live projections</h2><p>Actual results appear after reconciliation</p></div><button onclick={onreconcile} disabled={loading}>{loading ? 'Checking MLB…' : 'Reconcile results'}</button></div>{#if history.length}<div class="live-table"><div><b>Date</b><b>Pitcher</b><b>FIP P/A</b><b>Runs P/A</b><b>IP P/A</b><b>K P/A</b></div>{#each history.slice().reverse() as row}<div><span>{row.target_game_date}</span><strong>{row.pitcher_name}</strong><span>{value(row.projected_fip)} / {value(row.actual_fip)}</span><span>{value(row.expected_runs)} / {value(row.actual_runs)}</span><span>{value(row.expected_innings)} / {value(row.actual_innings)}</span><span>{value(row.expected_strikeouts)} / {value(row.actual_strikeouts)}</span></div>{/each}</div>{:else}<div class="validation-empty compact">No live projections have been recorded yet.</div>{/if}</section>
</main>
